package net.civeira.phylax.features.access.userconsentpurposes.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userconsentpurposes.domain.UserConsentPurposes;
import net.civeira.phylax.features.access.userconsentpurposes.domain.event.UserConsentPurposesEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserConsentPurposesEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserConsentPurposesEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserConsentPurposes entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
